import java.util.ArrayList;
import java.util.List;

class Main {
  public static void main(String[] args) {
    List<Integer> xs = new ArrayList<>();
    xs.add(1);
    xs.add(2);
    int sum = 0;
    for (int x : xs) sum += x;
    System.out.println(sum);
  }
}

